INSERT INTO productos (id, nombre, descripcion, detalle, precio, precio_original, descuento, imagen, alt, categoria, tag, personalizado) VALUES
(1, 'Torta de crema y frutilla', 'Bizcocho suave de vainilla con capas de crema chantilly y frutillas frescas, ideal para quienes disfrutan los sabores clásicos.', 'Ingredientes: Harina de trigo, huevos, azúcar, leche, mantequilla, crema para batir, frutillas y esencia de vainilla.', 3490, 3490, 0, '/images/comida/pastel_frutilla.jpg', 'pastel de frutilla', 'Tortas', 'Favorito', FALSE),
(2, 'Torta de chocolate', 'Torta de chocolate intenso con relleno cremoso y cobertura de ganache para los amantes del cacao.', 'Ingredientes: Harina de trigo, huevos, azúcar, cacao en polvo, chocolate, leche, mantequilla y crema.', 4490, 4490, 0, '/images/comida/pastel_chocolate.jpg', 'pastel de chocolate', 'Tortas', 'Favorito', FALSE),
(3, 'Cheesecake de frambuesa', 'Cheesecake suave y cremoso sobre una base crujiente de galletas, acompañado de salsa de frutos rojos.', 'Ingredientes: Queso crema, galletas, mantequilla, azúcar, huevos, crema de leche, frambuesas.', 4490, 4490, 0, '/images/comida/cheesecake_fram.jpg', 'cheesecake de frambuesa', 'Cheesecakes', NULL, FALSE),
(4, 'Pie de limón con merengue', 'Masa crujiente con relleno cítrico y una capa de merengue suave y ligeramente dorado.', 'Ingredientes: Harina de trigo, mantequilla, azúcar, huevos, leche condensada, limón y azúcar para el merengue.', 3490, 3490, 0, '/images/comida/pie_limon.jpg', 'pie de limón con merengue', 'Pies', NULL, FALSE),
(5, 'Torta tres leches', 'Bizcocho húmedo impregnado con una mezcla de tres leches y cubierto con crema chantilly.', 'Ingredientes: Harina de trigo, huevos, azúcar, leche evaporada, leche condensada, leche entera y crema para batir.', 3990, 3990, 0, '/images/comida/tres_leches.jpg', 'torta tres leches', 'Tortas', 'Favorito', FALSE),
(6, 'Mil hojas', 'Delicadas capas crujientes de masa con abundante manjar, terminadas con migas de hojaldre.', 'Ingredientes: Harina de trigo, mantequilla, huevos, azúcar, manjar y leche.', 4490, 4490, 0, '/images/comida/mil_hojas.jpg', 'mil hojas', 'Tortas', 'Favorito', FALSE),
(7, 'Torta de zanahoria', 'Bizcocho húmedo con zanahoria, especias suaves y una cobertura de queso crema.', 'Ingredientes: Harina de trigo, zanahoria, huevos, azúcar, aceite vegetal, canela, nueces y queso crema.', 3990, 3990, 0, '/images/comida/pastel_zana.jpg', 'torta de zanahoria', 'Tortas', NULL, FALSE),
(8, 'Kuchen de manzana', 'Pastel de manzana con un toque de canela y cubierta crocante de migas dulces.', 'Ingredientes: Harina de trigo, manzanas, mantequilla, azúcar, huevos, canela y leche.', 3490, 3490, 0, '/images/comida/kuchen_manzana.jpg', 'kuchen de manzana', 'Kuchen', NULL, FALSE),
(9, 'Brownie de chocolate', 'Brownie de textura húmeda, centro denso y sabor intenso a chocolate.', 'Ingredientes: Chocolate, cacao, harina, huevos, azúcar y mantequilla.', 2490, 2490, 0, '/images/comida/brownie.jpg', 'brownie de chocolate', 'Brownies', NULL, FALSE),
(10, 'Caja de 3 macarons surtidos', 'Pequeños bocados de almendra con exterior delicado y relleno cremoso. Disponibles en sabores como vainilla, frambuesa y chocolate.', 'Ingredientes: Harina, almendras, azúcar flor, claras de huevo, azúcar granulada, chocolate y crema.', 5990, 5990, 0, '/images/comida/macarons.jpg', 'caja de macarons surtidos', 'Macarons', NULL, FALSE),
(11, 'Rollito de crema y chocolate', 'Masa ligera rellena de crema pastelera de vainilla y terminada con cobertura de chocolate.', 'Ingredientes: Harina, huevos, mantequilla, leche, azúcar, vainilla, maicena y chocolate.', 1990, 1990, 0, '/images/comida/rollito_crema.jpg', 'rollito de crema', 'Rollitos', NULL, FALSE),
(12, 'Rollito de canela', 'Masa esponjosa enrollada con canela y azúcar, cubierta con un glaseado suave.', 'Ingredientes: Harina de trigo, leche, levadura, huevos, mantequilla, azúcar, canela y queso crema.', 2490, 2490, 0, '/images/comida/rollito_canela.jpg', 'rollito de canela', 'Rollitos', NULL, FALSE),
(13, 'Chilenito de manjar', 'Dos galletas suaves rellenas de manjar y espolvoreadas con azúcar flor.', 'Ingredientes: Harina de trigo, maicena, mantequilla, azúcar, huevos, manjar y azúcar flor.', 1490, 1490, 0, '/images/comida/chilenito.jpg', 'chilenito de manjar', 'Nacionales', NULL, FALSE),
