(15, 'Berlin crema pastelera', 'Masa dulce y esponjosa, rellena de crema pastelera y cubierta con azúcar flor.', 'Ingredientes: Harina de trigo, leche, levadura, huevos, mantequilla, azúcar, crema pastelera y aceite vegetal.', 1490, 1490, 0, '/images/comida/berlin_crema.jpg', 'berlin crema', 'Berlines', NULL, FALSE),
(16, 'Tartaleta de frutas', 'Base crujiente rellena de crema pastelera, decorada con frutillas frescas.', 'Ingredientes: Harina de trigo, mantequilla, azúcar, huevos, leche, maicena, vainilla y frutillas.', 3490, 3490, 0, '/images/comida/tartaleta_frutilla.jpg', 'tartaleta de frutas', 'Tortas', NULL, FALSE),
(17, 'Espresso', 'Café concentrado, aromático y con cuerpo, ideal para quienes prefieren disfrutar el sabor del grano sin leche.', 'Ingredientes: Café arabe de especialidad molido y agua filtrada.', 1990, 1990, 0, '/images/bebestible/espresso.jpg', 'espresso', 'Cafés', NULL, FALSE),
(18, 'Capuchino', 'Espresso combinado con leche vaporizada y una capa de espuma sedosa.', 'Ingredientes: Café arabe de especialidad molido, leche y agua filtrada.', 2990, 2990, 0, '/images/bebestible/capuchino.jpg', 'capuchino', 'Cafés', NULL, FALSE),
(19, 'Latte de vainilla', 'Espresso combinado con leche vaporizada, un toque de vainilla y una capa de espuma sedosa.', 'Ingredientes: Café arabe de especialidad molido, leche, jarabe de vainilla y agua filtrada.', 3490, 3490, 0, '/images/bebestible/latte_vainilla.jpg', 'latte', 'Cafés', 'Favorito', FALSE),
(20, 'Moka', 'Café con un toque de chocolate, ideal para los amantes del sabor intenso.', 'Ingredientes: Café arabe de especialidad molido, leche, chocolate y agua filtrada.', 3490, 3490, 0, '/images/bebestible/moka.jpg', 'moka', 'Cafés', NULL, FALSE),
