(22, 'Latte de caramelo', 'Espresso combinado con leche vaporizada y un toque de caramelo.', 'Ingredientes: Café arabe de especialidad molido, leche, caramelo y agua filtrada.', 3490, 3490, 0, '/images/bebestible/latte_caramelo.jpg', 'latte de caramelo', 'Cafés', 'Favorito', FALSE),
(23, 'Matcha rosa', 'Una bebida cremosa y refrescante hecha con polvo de matcha y un toque de frutilla.', 'Ingredientes: Polvo de matcha, leche, pure de frutilla y agua filtrada.', 3990, 3990, 0, '/images/bebestible/matcha.jpg', 'matcha rosa', 'Cafés', NULL, FALSE),
(24, 'Chocolate caliente', 'Una bebida caliente y reconfortante hecha con chocolate fundido y leche.', 'Ingredientes: Chocolate fundido, leche y agua filtrada.', 3490, 3490, 0, '/images/bebestible/chocolate.jpg', 'chocolate caliente', 'Cafés', NULL, FALSE);